 risk:["Young onset, family history of endocrine tumours, resistant hypertension on 3 drugs, low potassium, sleep apnoea, NSAIDs, decongestants, stimulants, alcohol"],
 comorb:["Sleep apnoea, CKD, PAD"],
 signs:["Phaeochromocytoma: episodic headache, sweating, palpitations, pallor, severe BP spikes. Conn's: low potassium, cramps, weakness, polyuria. Renal artery stenosis: abdominal bruit, kidney function worsening on ACE inhibitor"],
